import{_ as s,o as n,c as a,a6 as t}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"配置文件语法","description":"简单指令与块指令、上下文的定义、注释、计量单位与 include 的展开时机。","frontmatter":{"title":"配置文件语法","description":"简单指令与块指令、上下文的定义、注释、计量单位与 include 的展开时机。","source":"https://daiw.org/manual/nginx/config-syntax"},"headers":[],"relativePath":"manual/tools/nginx/config-syntax.md","filePath":"manual/tools/nginx/config-syntax.md"}'),o={name:"manual/tools/nginx/config-syntax.md"};function d(i,e,r,c,l,p){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="配置文件语法" tabindex="-1">配置文件语法 <a class="header-anchor" href="#配置文件语法" aria-label="Permalink to &quot;配置文件语法&quot;">​</a></h1><h2 id="指令是唯一的配置单位" tabindex="-1">指令是唯一的配置单位 <a class="header-anchor" href="#指令是唯一的配置单位" aria-label="Permalink to &quot;指令是唯一的配置单位&quot;">​</a></h2><p>官方文档的定义：</p><blockquote><p>nginx consists of modules which are <strong>controlled by directives</strong> specified in the configuration file.</p></blockquote><p><strong>nginx 由模块组成，模块由指令控制。</strong> 配置文件里没有别的东西——每一行不是指令就是注释。</p><h2 id="两类指令" tabindex="-1">两类指令 <a class="header-anchor" href="#两类指令" aria-label="Permalink to &quot;两类指令&quot;">​</a></h2><h3 id="简单指令" tabindex="-1">简单指令 <a class="header-anchor" href="#简单指令" aria-label="Permalink to &quot;简单指令&quot;">​</a></h3><blockquote><p>A simple directive consists of the <strong>name and parameters separated by spaces</strong> and ends with a <strong>semicolon</strong> (<code>;</code>).</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worker_processes  auto;</span></span>
<span class="line"><span>error_log         /var/log/nginx/error.log warn;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>名字 + 若干空格分隔的参数 + <strong>分号</strong>。分号不可省——漏写分号是最常见的语法错误。</p><h3 id="块指令" tabindex="-1">块指令 <a class="header-anchor" href="#块指令" aria-label="Permalink to &quot;块指令&quot;">​</a></h3><blockquote><p>A block directive has the same structure as a simple directive, but instead of the semicolon it ends with a <strong>set of additional instructions surrounded by braces</strong> (<code>{</code> and <code>}</code>).</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events {</span></span>
<span class="line"><span>    worker_connections  1024;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>结尾不是分号，而是一对花括号包住的一组指令。</p><p><strong>块指令的右花括号后面不加分号。</strong> 写 <code>} ;</code> 会报 <code>unexpected &quot;;&quot;</code>。</p><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><blockquote><p>If a block directive can have other directives inside braces, it is called a <strong>context</strong> (examples: <code>events</code>, <code>http</code>, <code>server</code>, and <code>location</code>).</p></blockquote><p><strong>能容纳其他指令的块指令叫「上下文」。</strong> 层级关系官方给得很明确：</p><blockquote><p>Directives placed in the configuration file <strong>outside of any contexts</strong> are considered to be in the <strong>main</strong> context. The <code>events</code> and <code>http</code> directives reside in the <code>main</code> context, <code>server</code> in <code>http</code>, and <code>location</code> in <code>server</code>.</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main                    ← 文件顶层，不在任何括号里</span></span>
<span class="line"><span>├── events { }</span></span>
<span class="line"><span>├── http {</span></span>
<span class="line"><span>│   ├── server {</span></span>
<span class="line"><span>│   │   └── location { }</span></span>
<span class="line"><span>│   └── upstream { }</span></span>
<span class="line"><span>├── stream {</span></span>
<span class="line"><span>│   └── server { }</span></span>
<span class="line"><span>└── mail { }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>每条指令都有自己允许出现的上下文清单</strong>，官方文档每条指令的第三行 <code>Context:</code> 就是它。写错位置的后果：</p><table tabindex="0"><thead><tr><th>情况</th><th>后果</th></tr></thead><tbody><tr><td>指令不允许出现在该上下文</td><td><strong>启动失败</strong>，报 <code>&quot;X&quot; directive is not allowed here</code></td></tr><tr><td>位置合法但不是你以为的那层</td><td><strong>静默生效在错误范围</strong>——最难查</td></tr></tbody></table><p>第二种才是真麻烦，详见<a href="/Front2Full/manual/tools/nginx/contexts">上下文与继承</a>。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><blockquote><p>The rest of a line after the <code>#</code> sign is considered a comment.</p></blockquote><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 整行注释</span></span>
<span class="line"><span>worker_processes auto;  # 行尾注释</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>只有 <code>#</code>，<strong>没有块注释语法</strong>。要注释掉一整段配置只能逐行加 <code>#</code>。</p><h2 id="计量单位" tabindex="-1">计量单位 <a class="header-anchor" href="#计量单位" aria-label="Permalink to &quot;计量单位&quot;">​</a></h2><p>官方 <a href="https://nginx.org/en/docs/syntax.html" target="_blank" rel="noreferrer">Configuration file measurement units</a> 定义了两套后缀。</p><h3 id="大小" tabindex="-1">大小 <a class="header-anchor" href="#大小" aria-label="Permalink to &quot;大小&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后缀</th><th>含义</th></tr></thead><tbody><tr><td><code>k</code> / <code>K</code></td><td>千字节</td></tr><tr><td><code>m</code> / <code>M</code></td><td>兆字节</td></tr><tr><td><code>g</code> / <code>G</code></td><td>吉字节——<strong>仅偏移量可用</strong></td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client_max_body_size  8m;</span></span>
<span class="line"><span>proxy_buffer_size     4k;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>注意 <code>g</code>/<code>G</code> 的限制：官方原话是 sizes and offsets 支持 k/m，而 <strong>offsets 才额外支持 g</strong>。所以 <code>client_max_body_size 1g;</code> 这类「大小」参数能不能写 <code>g</code> 取决于该指令的具体定义，写不了时会报参数无效。</p><h3 id="时间" tabindex="-1">时间 <a class="header-anchor" href="#时间" aria-label="Permalink to &quot;时间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>后缀</th><th>含义</th></tr></thead><tbody><tr><td><code>ms</code></td><td>毫秒</td></tr><tr><td><code>s</code></td><td>秒（<strong>默认</strong>）</td></tr><tr><td><code>m</code></td><td>分</td></tr><tr><td><code>h</code></td><td>时</td></tr><tr><td><code>d</code></td><td>天</td></tr><tr><td><code>w</code></td><td>周</td></tr><tr><td><code>M</code></td><td><strong>月 = 30 天</strong></td></tr><tr><td><code>y</code></td><td><strong>年 = 365 天</strong></td></tr></tbody></table><p>三条关键规则：</p><blockquote><p>A value without a suffix means <strong>seconds</strong>. It is recommended to <strong>always specify a suffix</strong>. Certain time intervals can be specified <strong>only with a seconds resolution</strong>.</p></blockquote><p><strong><code>m</code> 在大小里是「兆」，在时间里是「分」；<code>M</code> 在大小里是「兆」，在时间里是「月」。</strong> 同一个字母在两套单位里含义完全不同，靠所在指令的参数类型区分。</p><p>这正是官方建议「永远写后缀」的原因——<code>keepalive_timeout 60;</code> 是 60 秒，但读的人第一眼未必确定。写成 <code>60s</code> 无歧义。</p><p>时间可以叠加：<code>1h 30m</code> 等价于 <code>90m</code>、<code>5400s</code>。</p><h2 id="include" tabindex="-1">include <a class="header-anchor" href="#include" aria-label="Permalink to &quot;include&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>include /etc/nginx/conf.d/*.conf;</span></span>
<span class="line"><span>include /etc/nginx/mime.types;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>include</code> 是<strong>文本级展开</strong>，在解析时把目标文件内容原样插入当前位置。两个推论：</p><ol><li><strong>被包含文件的内容必须在该位置合法</strong>。放在 <code>http</code> 里的 include 文件中不能写 <code>events</code>。</li><li><strong>通配符按字母序展开</strong>——<code>conf.d/*.conf</code> 的加载顺序是文件名排序。依赖顺序时用数字前缀（<code>00-</code>、<code>10-</code>）。</li></ol><p><code>include</code> 找不到文件时<strong>启动失败</strong>；但用通配符且<strong>没有任何文件匹配</strong>时不报错（这是有意设计，允许目录为空）。</p><h2 id="语法检查" tabindex="-1">语法检查 <a class="header-anchor" href="#语法检查" aria-label="Permalink to &quot;语法检查&quot;">​</a></h2><p>改完配置<strong>永远先测</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx -t</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>输出 <code>syntax is ok</code> + <code>test is successful</code> 才算过。<code>-T</code> 额外把展开后的完整配置打印出来——排查 include 顺序与最终生效值时非常有用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx -T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/contexts">指令、上下文与继承</a>——nginx 配置里最容易出错的一环。</p>`,51)])])}const b=s(o,[["render",d]]);export{h as __pageData,b as default};
